<script setup lang="ts">
import {ref,onMounted} from 'vue'
import IdentityCard from '@/features/identity/ui/IdentityCard.vue'
import {effects,type EffectId} from '../config/effects'
import type {MockEncouragement} from '../adapters/encouragementMock'
const props=defineProps<{sender:'sample-a'|'sample-b';canSend:boolean;busy:boolean;error:string;history:MockEncouragement[];charge?:EffectId}>()
const emit=defineEmits<{close:[];preview:[effect:EffectId];send:[effect:EffectId,text:string]}>()
const chosen=ref<EffectId>('glow'),text=ref(''),closeButton=ref<HTMLButtonElement>()
onMounted(()=>closeButton.value?.focus())
function keys(event:KeyboardEvent){if(event.key==='Escape'){event.stopPropagation();if(!props.busy)emit('close')}if(event.key==='Tab'){const nodes=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not(:disabled),textarea:not(:disabled)')),first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
</script>
<template><div class="projection-backdrop" @click.self="!busy&&emit('close')"><section class="identity-projection" role="dialog" aria-modal="true" aria-label="支持者身份投影" :aria-busy="busy" @keydown="keys"><button ref="closeButton" class="projection-close" :disabled="busy" aria-label="收拢身份晶片" @click="emit('close')">×</button><IdentityCard variant="compact" dark :effect="charge" :identity="{nickname:sender==='sample-a'?'知夏':'亦安',role:'supporter',accountLabel:sender==='sample-a'?'SUPPORTER 01':'SUPPORTER 02'}"/>
 <div class="projection-effects" role="group" aria-label="选择鼓励光效"><button v-for="effect in effects" :key="effect.id" :data-projection-effect="effect.id" :aria-label="effect.label" :aria-pressed="chosen===effect.id" :disabled="busy" @click="chosen=effect.id"><span class="effect-miniature" :class="effect.id" aria-hidden="true"><i v-for="i in 5" :key="i" :style="{'--i':i}"/></span></button></div>
 <textarea v-if="canSend" v-model="text" :disabled="busy" maxlength="200" rows="2" placeholder="留言（可选）" aria-label="模拟鼓励留言"/>
 <p v-if="error" class="projection-error" role="alert">{{error}}</p><div class="projection-actions"><small>本页模拟</small><button :disabled="busy" @click="emit('preview',chosen)">预览</button><button v-if="canSend" class="projection-send" :disabled="busy" @click="emit('send',chosen,text)">{{busy?'处理中…':'模拟发送'}}</button></div>
 <details v-if="history.length" class="projection-history"><summary>互动记录 · {{history.length}}</summary><div v-for="record in history" :key="record.id"><span>{{effects.find(item=>item.id===record.effect)?.label}}</span><span>{{record.read?'本人已查看':'未查看'}}</span></div></details>
 </section></div></template>
<style scoped>
.projection-backdrop{position:fixed;inset:0;z-index:12;display:grid;place-items:center;padding:24px;background:#0e152440;backdrop-filter:blur(2px)}.identity-projection{position:relative;width:min(410px,100%);color:#dedfdc;font:12px Inter,'Microsoft YaHei',sans-serif;animation:identity-project .85s cubic-bezier(.2,.65,.2,1) both;perspective:1000px}.projection-close{position:absolute;right:-6px;top:-46px;font-size:23px}.identity-projection button{min-width:44px;min-height:44px;border:0;background:none;color:inherit;cursor:pointer;font-family:inherit}.identity-projection button:disabled{opacity:.4;cursor:wait}.projection-effects{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;padding:18px 0 8px}.projection-effects button{display:grid;place-items:center;border:1px solid #a8bfcc22;border-radius:10px;min-height:65px;background:#17233266}.projection-effects button[aria-pressed=true]{border-color:#e1c28c88;box-shadow:inset 0 0 15px #b6934622}.effect-miniature{position:relative;width:42px;height:42px}.effect-miniature i{position:absolute;width:3px;height:3px;border-radius:50%;background:#e8c887;left:calc(3px + var(--i)*6px);top:calc(3px + var(--i)*5px);box-shadow:0 0 7px #e8c88799}.starlight i{width:1px;height:16px;background:linear-gradient(#e3efff,transparent);transform:rotate(40deg)}.resonance i{width:calc(var(--i)*7px);height:calc(var(--i)*5px);left:50%;top:50%;transform:translate(-50%,-50%);background:none;border:1px solid #c2dbe866;box-shadow:none}.bloom i{width:8px;height:20px;left:50%;top:50%;transform:translate(-50%,-100%) rotate(calc(var(--i)*72deg));transform-origin:50% 100%;background:#ddcda633;border:1px solid #e5d3ae88;box-shadow:none}.halo i{left:calc(19px + sin(var(--i)*72deg)*17px);top:calc(19px + cos(var(--i)*72deg)*12px);background:#d9e9ff}.identity-projection textarea{width:100%;box-sizing:border-box;padding:12px 2px;border:0;border-bottom:1px solid #a4b5c444;background:#17233233;color:#e4e6e7;font:inherit;resize:none;outline:none}.identity-projection textarea:focus{border-color:#ddc38c}.projection-actions{display:flex;align-items:center;gap:8px;margin-top:8px}.projection-actions small{font-size:9px;color:#a8b6c4;flex:1}.projection-send{border:1px solid #d8bd8288!important;border-radius:20px;padding:0 15px}.projection-error{color:#ebba97;font-size:12px;line-height:1.7}.projection-history{margin-top:12px;color:#aab9c6;font-size:10px}.projection-history summary{cursor:pointer;padding:12px 0}.projection-history div{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid #9cabb322}.identity-projection :focus-visible{outline:2px solid #ceb786;outline-offset:4px}@keyframes identity-project{from{opacity:0;transform:translateY(25px) rotateX(10deg) scale(.65)}to{opacity:1;transform:none}}@media(max-width:600px){.projection-backdrop{padding:20px}.projection-effects{gap:5px}}@media(prefers-reduced-motion:reduce){.identity-projection{animation:none}}
</style>
